def greedy_set_cover_mipstart(model, y_vars, demand_items, facility_coverage):
    uncovered = set(demand_items)
    selected = set()
    while uncovered:
        best = max(facility_coverage.keys(), key=lambda j: len(facility_coverage[j] & uncovered))
        selected.add(best)
        uncovered -= facility_coverage[best]
    for j in y_vars:
        model.getVarByName(f'y_{j}').Start = 1.0 if j in selected else 0.0

def greedy_submodular_max(model, candidate_set, k, f_eval):
    chosen = set()
    remaining = set(candidate_set)
    while len(chosen) < k:
        best = max(remaining, key=lambda j: f_eval(chosen | {j}) - f_eval(chosen))
        chosen.add(best)
        remaining.remove(best)
    for j in candidate_set:
        model.getVarByName(f'x_{j}').Start = 1.0 if j in chosen else 0.0
